doc({id:'responsive',title:'Responsive',icon:'monitor',lead:'Components change at breakpoints; they don’t just shrink.',render(){_n=0;const k=FL();const d3=(fn)=>`<div class="devs">${[['desktop','Desktop'],['tablet','Tablet'],['mobile','Mobile']].map(([v,l])=>`<div><span>${l}</span><div class="dev dev--${v}">${stageHTML(k,fn(v))}</div></div>`).join('')}</div>`;
  return `${head('Guidelines','Responsive','Components change at breakpoints; they don’t just shrink.')}${sec2('Breakpoints','',tableHTML(['Range','Layout','Navigation','Comparison benches'],[['Desktop ≥ 1180px','12 columns','Sidebar','Side by side'],['Tablet 700–1179px','8 columns','Menu button','Scroll sideways'],['Mobile < 700px','4 columns','Menu + drawer','One language at a time']]))}
  ${sec2('Stepper','Horizontal → scroll → vertical.',d3(v=>stRender({variant:'numbered',layout:'horizontal',icon:'check',scheme:'semantic',state:'active',content:'desc',device:v},k)))}
  ${sec2('Buttons','Inline → full width.',d3(v=>DOCS['components/buttons'].render({variant:'primary',layout:'single',icon:'leading',state:'default',content:'text',device:v},k)))}
  ${sec2('Calendar','Month → agenda.',d3(v=>DOCS['components/calendar'].render({variant:'month',device:v},k)))}
  ${sec2('Touch targets','',tableHTML(['Size',...ALL4.map(x=>SYS[x].short),'Material'],[['Small','24px','24px','28px','22px','32px'],['Medium','32px','32px','36px','28px','40px'],['Large','40px','40px','44px','36px','48px']]))}`}});
doc({id:'content-guidelines',title:'Content',icon:'pen',lead:'How the interface speaks, in every language and module.',render(){_n=0;return `${head('Guidelines','Content guidelines','How the interface speaks, in every language and module.')}${sec2('Principles','',`<ul class="princ-list"><li>Name things by what users recognise: “notifications”, not “webhook config”.</li><li>Buttons say what happens: “Approve”, then confirm with “Approved”.</li><li>Errors say what went wrong and how to fix it, without blame.</li><li>Sentence case everywhere; numbers as digits; dates as “Oct 20, 2026”.</li></ul>`)}${sec2('Examples','',tableHTML(['Context','Do','Don’t'],[['Primary button','Create purchase order','Submit'],['Error','PO number must look like PO-2291','Invalid input'],['Empty state','No orders match these filters. Clear filters','No data'],['Destructive confirm','Delete 3 orders? This can’t be undone.','Are you sure?'],['Toast','PO-2292 was saved','Success!'],['Money','$86,400.00','86400'],['Status','Awaiting approval','Pending (status 3)']]))}`}});
doc({id:'comparison',title:'Comparison',icon:'columns',lead:'All five design languages: specification, the same screen, and when to choose each.',render(){_n=0;return `${head('Guidelines','Design language comparison','All five design languages: specification, the same screen, and when to choose each.')}${sec2('Specification','',langTable(LSPEC_ROWS,LANGS))}${sec2('Same screen','Identical markup and content.',`<div class="bench" style="--n:1">${LANGS.map(k=>`<section class="lab-col"><header class="lab-col__h"><b>${SYS[k].name}</b><span>${SYS[k].tag}</span></header>${stageHTML(k,sampler(k))}</section>`).join('')}</div>`)}${sec2('When to choose which','',tableHTML(['Language','Best for','Avoid for'],LANGS.map(k=>[SYS[k].name,LINFO[k].best.join(', '),LINFO[k].avoid.join(', ')])))}${sec2('Recommendation','',`<div class="rec-box"><small>Recommended default for ERP / CRM</small><b>Chroma, at Comfortable density for most modules and Compact for data entry</b><p>Chroma’s colour coding, open rows and clear focus ring suit complex workflows; the Compact density keeps the same colours with tighter rows for data-entry teams. Choose by workflow and user context, not preference.</p></div>`)}`}});
doc({id:'foundations',title:'Foundations',icon:'layers',lead:'All foundation pages.',render(){return `${head('Foundations','Foundations','The Chroma visual rules every component reads.')}<div class="hub">${NAV[0][1].filter(id=>id!=='index').map(id=>`<a href="${href(id)}"><b>${DOCS[id].title}</b><span>${DOCS[id].lead||''}</span></a>`).join('')}</div>`}});
doc({id:'design-languages',title:'Design Languages',icon:'palette',lead:'All design language pages.',render(){return `${head('Design languages','Design languages','Five visual languages over one component architecture.')}<div class="hub">${NAV[1][1].map(id=>`<a href="${href(id)}"><b>${DOCS[id].title}</b><span>${DOCS[id].lead}</span></a>`).join('')}</div>${langTable(LSPEC_ROWS.slice(0,6),LANGS)}`}});

